\begin{thm}\label{thmudot3}
Let Assumptions 1--4 hold. Given arbitrary initial conditions in $x(0)\in\Re^n$ and $\norm{\theta(0)}\leq \theta_\text{max}$, if $\ell\geq\ell^\prime$ the derivative $\dot u$ satisfies the following two inequalities:
\be
\begin{split}
 \sup_{t\in T_i^{\prime\prime}}\abs{\dot u(t)} \leq &\left(\frac{m^2\gamma}{\sigma+2\ell}\norm b G^{\prime\prime}_{e,i}G^{\prime\prime}_{x,i} +8\eta  \theta^2_\text{max}\right)G^{\prime\prime}_{x,i}   \\ & + \theta_\text{max}\left(a_\theta G^{\prime\prime}_{x,i}+r_0\right) + r_1\label{ub13}
\end{split}
\ee where
\be\label{GS3}\begin{split}
G^{\prime\prime}_{x,1}\triangleq & (1+\delta_1) \norm{e(0)} +\frac{\delta_1 \norm b }{a_\theta}r_0\\
G^{\prime\prime}_{e,1}\triangleq & \sqrt{\kappa_7}\left( \norm{e_m(0)} +\norm{e_i(0)}\right) + \sqrt{\frac{\kappa_8}{\rho}} {\tilde\theta_\text{max}} \\
G^{\prime\prime}_{x,2}\triangleq &\kappa_9 \left( \norm{e_m(0)} +\norm{e_i(0)}\right) +
\left(2+\kappa_{10} \ell \right) \sqrt{\frac{\kappa_8}{\rho}} {\tilde\theta_\text{max}} 
\\ &+\kappa_{11} r_0\\
G^{\prime\prime}_{e,2}\triangleq  & \sqrt{\kappa_7}\left( \norm{e_m(0)} +\norm{e_i(0)}\right) \epsilon_1 + \sqrt{\frac{\kappa_8}{\rho}} {\tilde\theta_\text{max}} \\
G^{\prime\prime}_{x,3}\triangleq &\kappa_{12} \left( \norm{e_m(0)} +\norm{e_i(0)}\right) +\epsilon\\& +
\left(2+\kappa_{10} \ell \right) \sqrt{\frac{\kappa_8}{\rho}} {\tilde\theta_\text{max}} +\kappa_{11} r_0\\
G^{\prime\prime}_{e,3}\triangleq &\epsilon.
\end{split}
\ee
with $\epsilon_1 = \exp(-N)$



\end{thm}
\begin{proof}
The finite time stability result used in \eqref{finitex} still holds for the MMRAC--C. Therefore $G^{\prime\prime}_{x,1}$ in \eqref{GS3} is identical to $G_{x,1}$ in  \eqref{GS}. The Lyapunov function in \eqref{s8:v} has two additional terms in $e_i$ and $\bar \theta$ as compared to the Lyapunov equation in \eqref{can}. Therefore, $G^{\prime\prime}_{e,1}$ now includes the initial conditions of the estimation error $e_i(0)$. $G^{\prime\prime}_{x,2}$ and $G^{\prime\prime}_{e,2}$ are similarly affected. Barbalat Lemma can be used for $G_{e,3}^{\prime\prime}$, and $G_{x,3}^{\prime\prime}$ follows from the same analysis in Appendix \ref{ut3}. The $\eta$ terms arise from the righthand side of the update law in \eqref{s8:law}.
\end{proof}

Robustness of CMRAC--CO to Noise
As mentioned earlier, the benefits of the CMRAC--CO is the use of the observer state $x_o$ rather than the actual plant state $x$. Suppose that the actual plant dynamics is modified from \eqref{s1:sys} as
\be\label{p:n}
\dot x_a(t)= A_p x_a(t)+b u(t), \qquad x(t)=x_a(t)+n(t)
\ee
where $n(t)$ represents measurement noise. For ease of exposition, we assume that $n(t)$ is  bounded and deterministic.


This leads to a set of modified error equations
\be
\begin{split}\label{cne}
\dot e_m(t) =& (A_m+L_m) e_m +b \tilde \theta ^T (t)x_o +b\theta^*e_o  +L_m n(t) \\
\dot e_o(t) =& (A_m+L_o-b\theta^*) e_o -b \bar \theta ^T (t)x_o -L_o n(t)
\end{split}
\ee









\begin{thm}\label{lem:cmraco}
Let Assumptions \ref{asm:m} and \ref{asm:thetas} hold with $\ell$ chosen such that $\ell\geq \ell^{\prime\prime}$. Consider the overall CMRAC--CO specified by \eqref{p:n}, \eqref{s1:ref}, \eqref{s6:u},  \eqref{s6:o}, \eqref{cne} and \eqref{s6:law}. For any initial condition $e_m(0),e_o(0)\in \Re^n$, and $\theta(0)$ and $\hat\theta(0)$ such that $\norm{\theta(0)}\leq\theta_\text{max}$ and $\norm{\hat\theta(0)}\leq\theta_\text{max}$, it can be shown that $e_m(t)$, $e_o(t)$, $\theta(t)$ and $\hat\theta(t)$ are uniformly bounded for all $t\geq0$ and the trajectories in the function $V$ from \eqref{s6:v} converges exponentially 
as
\be
\dot V \leq -\alpha_7 V + \alpha_{8}
\ee
where
\be\begin{split}\label{s11:a}
\alpha_7 \triangleq& \frac{\left(1-\Delta(\ell ) \right)\left(\sigma+ 2\ell \right)}{2m^2} , \\ \alpha_{8} \triangleq&  \frac{\left(1-\Delta(\ell ) \right)\left(\sigma+ 2\ell \right)}{\gamma m^2} \tilde\theta_\text{max}^2\\ &+ \frac{16}{\left(1-\Delta(\ell ) \right)^2} \left(\frac{m^2}{\sigma+2 \ell}\right)^2 \norm{n(t)}^2\end{split}\ee
and\ben\begin{split}
\mathcal E \triangleq \left\{   (e_m,e_o,\tilde\theta,\bar\theta) \right | & \norm{e_m}^2  \leq \beta_6 \tilde\theta_\text{max}^2+\beta_7 \norm{n(t)}^2,  \\  &  \left.\norm{e_o}^2 \leq \beta_6  \tilde\theta_\text{max}^2 +\beta_7 \norm{n(t)}^2, \right.   \\ &  \left.\norm {\tilde \theta} \leq \tilde\theta_\text{max},\ \norm {\bar \theta} \leq \tilde\theta_\text{max} \right\}
\end{split}
\een
with $\beta_6$ defined in \eqref{s6:b} and $\beta_7$ defined as
\be\label{s8:b}
\beta_7 \triangleq \frac{64 m^2 s}{\sigma(1-\Delta(\ell))^3}
\ee
\end{thm}
\begin{proof}see Appendix \ref{applemcmrac}\let\IEEEQEDopen\relax\end{proof}

